function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'RLEIterator' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with RLEIterator and its encoding.';
  const encoding = args[0][0];
  if (!Array.isArray(encoding) || encoding.length < 2 || encoding.length > 1000) return 'encoding needs 2 to 1000 numbers.';
  if (encoding.length % 2 !== 0) return 'encoding needs an even length.';
  if (encoding.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each encoding number is between 0 and 10^9.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to next.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'next') return 'Only next can follow the constructor.';
    const n = args[i]?.[0];
    if (!Array.isArray(args[i]) || args[i].length !== 1 || !Number.isInteger(n) || n < 1 || n > 1e9) return 'next takes one whole number from 1 to 10^9.';
  }
  return null;
}

