class RLEIterator {
  // Track how many items were consumed in total, then locate that item by re-adding the counts from the start.
  constructor(encoding) {
    this.encoding = encoding.slice();
    this.consumed = 0;
  }
  next(n) {
    this.consumed += n;
    let seen = 0;
    for (let i = 0; i < this.encoding.length; i += 2) {
      seen += this.encoding[i];
      if (seen >= this.consumed) return this.encoding[i + 1];
    }
    return -1;
  }
}

