function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const mode = int(0, 2);
  const countTop = large ? [3, 1000000, 1000000000][mode] : [2, 4, 1000000000][mode];
  const stepTop = large ? [3, 1000000, 1000000000][mode] : [3, 6, 1000000000][mode];
  const pairs = large ? 500 : int(1, 4);
  const valueTop = large || rand() < 0.3 ? 1000000000 : 5;
  const encoding = [];
  for (let i = 0; i < pairs; i++) {
    encoding.push(rand() < 0.15 ? 0 : int(0, countTop), int(0, valueTop));
  }
  const calls = large ? 499 : int(1, 10);
  const operations = ['RLEIterator'];
  const args = [[encoding]];
  for (let i = 0; i < calls; i++) {
    operations.push('next');
    args.push([int(1, stepTop)]);
  }
  return [operations, args];
}
